import {DISPLAY_ROSTER,STAT_NAMES} from './data.js?v=202';
export function teamBalance(ids){const agents=DISPLAY_ROSTER.filter(a=>ids.includes(a.id));return STAT_NAMES.map((name,i)=>({name,total:agents.reduce((n,a)=>n+a.stats[i],0),best:Math.max(0,...agents.map(a=>a.stats[i]))}));}
export function teamBalanceMarkup(ids,previewId=null){const candidate=DISPLAY_ROSTER.find(a=>a.id===previewId&&!ids.includes(a.id)),current=teamBalance(ids),rows=teamBalance(candidate?[...ids,candidate.id]:ids);return `<section class="team-balance panel ${candidate?'is-preview':''}"><h3>${candidate?'Équilibre avec '+candidate.name:'Équilibre de votre équipe'}</h3><p>${candidate?'Aperçu avant confirmation · totaux sur 40':'Totaux sur 40 · choisissez au moins un spécialiste à 7 ou plus dans chaque capacité.'}</p>${rows.map((r,i)=>`<div class="balance-row ${r.best<7?'gap':''}"><span>${r.name}</span><meter min="0" max="40" value="${r.total}" aria-label="${r.name} : ${candidate?'avec '+candidate.name+' : ':''}${r.total} sur 40"></meter><strong>${candidate?`<span class="balance-before">${current[i].total} → </span>`:''}${r.total}/40</strong><small>${candidate?`<b class="balance-gain">+${candidate.stats[i]}</b> · `:''}${r.best<7?'À renforcer':'Spécialiste présent'} · meilleur ${r.best}/10</small></div>`).join('')}<small>Analyse : preuves et préparation · Habileté : contacts, mandat et numérique · Sang-froid : interventions et discrétion. Un total élevé ne remplace pas les talents adaptés. Ces conseils ne bloquent pas le lancement.</small></section>`;}
